 useEffect(()=>{if(!data)return;const now=new Date(),from=new Date(now.getTime()-24*3600000),to=new Date(now.getTime()-data.settings.missedGraceMinutes*60000);let logs=data.doseLogs.slice(),changed=false;for(const m of data.medicines.filter(m=>m.isActive))for(const at of occurrences(m,from,to)){if(now.getTime()-at.getTime()<data.settings.missedGraceMinutes*60000)continue;if(!logs.some(l=>l.medicineId===m.id&&l.scheduledAt===at.toISOString())){logs.push({id:id(),medicineId:m.id,scheduledAt:at.toISOString(),localDate:day(at),status:'missed',actedAt:now.toISOString(),snoozeCount:0});changed=true;}}if(changed){const n={...data,doseLogs:logs};setData(n);void localStore.write(n);}},[data]);
