 const openForm=(m?:Medicine)=>{setEdit(m??null);Sname(m?.name??'');Sstrength(m?.strength??'');setMedicineForm(m?.form??'tablet');Stimes(m?.schedule.timesMinutes.map(n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')).join(', ')??'08:00');Sqty(String(m?.doseQuantity??1));Sunit(m?.doseUnit??'tablet');Sinstructions(m?.instructions??'');SfrequencyText(m?.frequencyText??'');SdurationText(m?.durationText??'');Stype(m?.schedule.type??'daily');Sdays(m?.schedule.weekdaysMask?Array.from({length:7},(_,i)=>i).filter(i=>!!(m.schedule.weekdaysMask!&(1<<i))):[0,1,2,3,4,5,6]);Sinterval(String(m?.schedule.intervalDays??2));Sanchor(m?.schedule.anchorDate??day());Sstart(m?.startDate??day());Send(m?.endDate??'');Sstock(m?.stockCount===undefined?'':String(m.stockCount));Sthreshold(String(m?.refillThreshold??5));SphotoUri(m?.photoUri??'');setShowTimeOptions(false);setCustomTime('');setForm(true);};
